fn shortest_paths(g, start):
    var dist = [Vertex]none
    dist[start] = 0
    var queue = MinHeap((0, start))
    while let (d, u) = queue.pop():
        if d != dist[u]: continue
        for (v, weight) in g.neighbors(u):
            if dist[v] == none or d + weight < dist[v]:
                dist[v] = d + weight
                queue.push((dist[v], v))
    dist
